let toastTimer,raf,lastFrame=0,lastDraw=0;

function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,2800)}
function go(page){location.hash=page;if(state.page===page)render()}
function pageTitle(eyebrow,title,sub,extra=''){return `<div class="intro"><div class="heading-row"><h1>${title}</h1>${extra}</div>${sub?`<p class="subtitle">${sub}</p>`:''}</div>`}
function render(){state.page=['home','start','records','knowledge','captions','settings','usage'].includes(location.hash.slice(1))?location.hash.slice(1):'home';document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===state.page));$('#session-nav').hidden=!state.started&&state.tick===0;$('#breadcrumb').innerHTML=`工作空间 <b>/</b> ${{usage:'用量',home:'首页',records:'记录',start:'添加领域',knowledge:'知识空间',captions:'当前会话',settings:'偏好设置'}[state.page]}`;$('#count').textContent=String(state.cache?1:0);$('#record-count').textContent=String(state.records.length);document.body.classList.toggle('onboarding',state.onboarding);document.body.classList.toggle('focus-mode',state.focused);$('#app').innerHTML=`<section class="page">${state.onboarding?onboardPage():state.page==='home'?homePage():state.page==='start'?(state.generating?processPage():startPage()):state.page==='usage'?usagePage():state.page==='records'?recordsPage():state.page==='knowledge'?spacePage():state.page==='settings'?settingsPage():captionsPage()}</section>`;if(state.generating)updateProgress();syncOverlay();updateCaption();filterTranscript();afterRecordRender();let back=$('#return-client');if(!back){back=document.createElement('button');back.id='return-client';back.dataset.action='unfocus';back.textContent='↖ 返回主窗口';document.body.append(back)}back.hidden=!state.focused}
function onboardPage(){const step=state.onboardStep;return `<div class="onboard-shell"><div class="onboard-top"><span class="brand">▥ livecap <small class="preview-badge">设计预览</small></span><button class="ghost small" data-action="finish-onboarding">稍后配置</button></div><div class="onboard-steps">${['欢迎','连接服务','内容领域','准备就绪'].map((x,i)=>`<span class="${i===step?'active':''}">${i+1} ${x}</span>`).join('')}</div>${step===0?`<div class="welcome"><div class="welcome-wave">${'<i></i>'.repeat(5)}</div><h1>让语言退到背景里。</h1><p>听会议、看视频，用熟悉的语言跟上每一句。</p><div class="welcome-caption"><small>English → 简体中文</small><h2>听懂当下，也留住值得回看的内容。</h2><p>Understand the moment. Keep what matters.</p></div><button class="primary" data-action="onboard-next">配置我的 Livecap →</button></div>`:step===1?`<div class="onboard-connect"><h1>连接你的翻译服务</h1><p class="subtitle">使用自己的 API 服务，开启实时转录和翻译。</p><div class="connection"><div class="connection-head"><strong>OpenAI</strong><span class="service-mark">${state.connected?'演示连接就绪':'未连接'}</span></div><p>实时转录 · Luna 翻译</p><button data-action="demo-connect" class="small">${state.connected?'已就绪':'体验连接流程'}</button></div><div class="onboard-next"><button class="ghost" data-action="onboard-back">上一步</button><button class="primary" data-action="onboard-next">继续 →</button></div></div>`:step===2?(state.generating?processPage():startPage()+`<div class="onboard-next"><button class="ghost small" data-action="onboard-back">上一步</button><button class="ghost small" data-action="onboard-next">先使用通用翻译 →</button></div>`):`<div class="welcome"><div class="ready-mark">✓</div><h1>准备就绪</h1><p>${state.cache?esc(state.cache.name)+' 已加入知识空间':'先从通用翻译开始，随时添加领域知识。'}</p><div class="ready-list"><span>声音来源 <b>系统音频</b></span><span>字幕窗口 <b>底部停靠，可拖动</b></span><span>音频与字幕 <b>默认保存到本地</b></span></div><button class="primary" data-action="finish-onboarding">进入 Livecap →</button></div>`}</div>`}
function homePage(){return `${pageTitle('','首页','')}<div class="home-hero"><div><span class="home-eyebrow">LIVE TRANSLATION</span><h2>${state.started?'字幕正在为你工作':'打开字幕，继续你的内容。'}</h2><p>系统音频 · ${languagePair()}</p></div><button class="primary" data-action="${state.started?'focus-session':'launch-session'}">${state.started?'查看字幕窗':'开始字幕'} ↗</button></div><div class="home-options"><span>当前领域 <b>${state.cache?esc(state.cache.name):'通用'}</b></span><button class="small" data-go="start">添加领域</button><button class="small" data-go="settings">字幕与服务设置</button>${state.started?'<button class="small" data-go="captions">管理当前会话</button>':''}</div><div class="section-toolbar"><h3>最近记录</h3><button class="ghost small" data-go="records">查看全部 →</button></div>${recordList()}<div class="home-guide"><span>随时调整你的声音来源、字幕外观和专业领域。</span><button class="ghost small" data-action="reconfigure">重新配置 →</button></div>`}
function recordList(){return recordCards()}
function recordsPage(){return recordWorkspace()}
function spacePage(){return `${pageTitle('','知识空间','领域资料、专业术语与确认后的学习积累。')}<div class="space-tabs">${[['domains','领域知识'],['learned','学习积累']].map(([id,label])=>`<button data-space="${id}" class="${state.knowledgeTab===id?'active':''}">${label}</button>`).join('')}</div>${state.knowledgeTab==='domains'?domainPanel():`<div class="records-empty"><span>✧</span><h3>让使用过的内容成为下一次的帮助</h3><p>这里将收集记录中发现的术语与人工修正。</p><small>尚无待确认的学习内容</small></div>`}`}
function domainPanel(){return `<div class="section-toolbar"><h3>${state.cache?esc(state.cache.name):'领域知识'}</h3><button class="small" data-go="start">＋ 添加领域</button></div>${state.cache?`<div class="domain-coverage"><span>词汇示例</span><p>当前原型展示部分示例；完整知识库按主题、资料来源与术语组织。</p></div><div class="section-toolbar"><h3>术语示例</h3><input class="search" id="search" aria-label="搜索术语" placeholder="搜索术语或译法…"></div><div class="term-grid" id="terms">${termCards('')}</div>`:'<div class="records-empty"><h3>为经常接触的内容添加领域</h3><p>编程、设计、商业，或你自己的专业方向。</p></div>'}`}
function finishOnboarding(){state.onboarding=false;try{localStorage.setItem('livecap.client.onboarded','1')}catch{}go('home');render()}
function saveRecord(){const lines=state.history.map(x=>({...x}));const zh=$('.current-caption .cap-zh')?.textContent,en=$('.current-caption .cap-en')?.textContent;if(zh)lines.push({time:Math.floor(state.tick/7)*7,zh,en:en||''});if(!lines.length){toast('暂无可保存的字幕');return}state.records.unshift({title:(state.cache?.name||'字幕')+' · '+new Date().toLocaleDateString('zh-CN'),date:new Date().toLocaleString('zh-CN'),duration:state.tick,lines});try{localStorage.setItem('livecap.client.records',JSON.stringify(state.records))}catch{toast('保存失败');return}state.selectedRecord=0;go('records');render()}
function startPage(){let d=domains[state.domain];return `${pageTitle('A LITTLE CONTEXT. A LOT MORE CLARITY.','选择内容领域','为转录与翻译添加专业词汇。','')}<div class="domains" role="group" aria-label="选择内容领域">${domains.map((d,i)=>`<button class="domain ${i===state.domain?'selected':''}" data-domain="${i}" aria-pressed="${i===state.domain}"><span class="check" aria-hidden="true">✓</span><span class="icon" aria-hidden="true"><svg viewBox="0 0 36 36">${icons[i]}</svg></span><strong>${d.name}</strong><small>${d.desc}</small></button>`).join('')}</div><div class="focus-area"><div class="label-line">${state.domain===5?'领域名称':'细分方向'}<span>${state.domain===5?'例如：半导体制造、音乐制作':''}</span></div>${state.domain===5?`<input class="custom-input" id="custom" aria-label="自定义领域" placeholder="输入你感兴趣的领域…" maxlength="80" value="${esc(state.custom)}">`:`<div class="chips">${d.focus.map(f=>`<button class="chip ${f===state.focus?'selected':''}" data-focus="${f}" aria-pressed="${f===state.focus}">${f}</button>`).join('')}</div>`}</div><div class="setup-footer"><div class="hint">生成后自动保存到本地</div><button class="primary" data-action="generate" ${state.domain===5&&!state.custom.trim()?'disabled':''}>生成知识库 <span class="arrow">↗</span></button></div>`}
function processPage(){return `<div class="process"><div class="process-symbol working" aria-hidden="true">✳</div><h1>正在准备领域示例</h1><p class="subtitle">${esc(state.domain===5?state.custom:state.focus)}</p><div class="progress-panel"><div class="progress-head"><span id="progress-label">正在准备</span><span id="percent">0%</span></div><div class="progress-track" role="progressbar" aria-label="生成进度" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><div id="progress-fill"></div></div>${[['查找参考资料','从文档与公开资料中建立上下文'],['整理术语与表达','保留专有名词，补充含义与译法'],['建立本地知识缓存','整理成可复用的知识文件']].map((s,i)=>`<div class="stage" data-stage="${i}"><span class="stage-num">${i+1}</span><div>${s[0]}<small>${s[1]}</small></div></div>`).join('')}</div><div class="source-ticker" id="source-ticker">正在准备资料…</div><div class="process-actions"><button class="small" data-action="pause-generation">${state.paused?'继续':'暂停'}</button><button class="small ghost" data-action="cancel-generation">取消</button></div></div>`}
function updateProgress(){if(!$('#progress-fill'))return;let p=Math.round(state.progress),stage=Math.min(2,Math.floor(p/34));$('#progress-fill').style.width=p+'%';$('.progress-track').setAttribute('aria-valuenow',p);$('#percent').textContent=p+'%';$('#progress-label').textContent=state.paused?'已暂停':'正在整理';$('.process-symbol').classList.toggle('working',!state.paused);document.querySelectorAll('.stage').forEach((el,i)=>{el.classList.toggle('active',i===stage);el.classList.toggle('done',i<stage);el.querySelector('.stage-num').textContent=i<stage?'✓':i+1});$('#source-ticker').textContent=['参考资料 · '+domains[state.domain].source,'术语、定义与上下文正在逐项整理…','knowledge / '+cacheSlug()+'.json'][stage]}
function cacheSlug(){return state.domain===0&&state.focus==='LLVM / Clang'?'llvm-clang':['programming','design','business','research','everyday','custom'][state.domain]}
function beginGeneration(){if(state.generating)return;state.progress=0;state.paused=false;state.generating=true;render();state.timer=setInterval(()=>{if(state.paused)return;state.progress=Math.min(100,state.progress+2);updateProgress();if(state.progress>=100){clearInterval(state.timer);state.generating=false;const d=domains[state.domain];state.cache={name:state.domain===5?state.custom:state.focus,domain:d.name,slug:cacheSlug(),source:state.domain===0&&state.focus!=='LLVM / Clang'?'技术术语':d.source,url:state.domain===0&&state.focus!=='LLVM / Clang'?'':d.url,entries:(state.domain===0&&programmingExamples[state.focus]||d.terms).map((t,i)=>({id:i,term:t[0],translation:t[1],meaning:t[2]})),example:true};if(state.autoCache)persist();if(state.onboarding){state.onboardStep=3;render()}else{state.knowledgeTab='domains';go('knowledge')}toast('领域示例已准备')}},160)}
function knowledgePage(){if(!state.cache)return `${pageTitle('YOUR PERSONAL CONTEXT','知识空间','')}<div class="empty"><div class="process-symbol">▦</div><h2>还没有知识库</h2><p>添加一个领域，开始积累专业词汇。</p><button class="primary" data-go="start">选择领域 <span class="arrow">↗</span></button></div>`;let c=state.cache;return `${pageTitle('A SPACE THAT SPEAKS YOUR LANGUAGE',esc(c.name),'','<button class="small" data-go="start">＋ 新建知识库</button>')}<div class="result-banner"><div><h3>✓ 已保存到本地</h3><p>${esc(c.name)} · ${c.entries.length} 个术语</p></div><div class="stats"><div class="stat"><b>${c.entries.length}</b>术语</div></div></div><div class="section-toolbar"><h3>术语与表达 <span class="hint"> / ${esc(c.domain)}</span></h3><input class="search" id="search" aria-label="搜索术语" placeholder="搜索术语或译法…"></div><div class="term-grid" id="terms">${termCards('')}</div><div class="results-actions"><button class="ghost small" data-action="export">↓ 导出</button><button class="primary" data-go="captions">使用此知识库 <span class="arrow">→</span></button></div>`}
function termCards(query){const list=state.cache.entries.filter(e=>(e.term+e.translation+e.meaning).toLowerCase().includes(query.toLowerCase()));return list.length?list.map(e=>`<button class="term-card" data-term="${e.id}"><div class="term-top"><strong>${esc(e.term)}</strong><span class="tag">术语</span></div><p>${esc(e.translation)} · ${esc(e.meaning)}</p><small>${esc(state.cache.source)} <span style="float:right">↗</span></small></button>`).join(''):'<p class="subtitle">没有匹配的术语，试试其他关键词。</p>'}
function openTerm(id){const e=state.cache.entries.find(x=>x.id===id);const dialog=$('#detail');dialog.innerHTML=`<div class="dialog-top"><div><h2>${esc(e.term)}</h2></div><button class="ghost small" data-action="close-dialog" aria-label="关闭术语详情">✕</button></div><p>${esc(e.meaning)}</p><div class="field-label">字幕中的译法</div><input id="translation-edit" aria-label="字幕中的译法" maxlength="100" value="${esc(e.translation)}"><div class="field-label">参考来源</div>${state.cache.url?`<a class="source-link" href="${state.cache.url}" target="_blank" rel="noopener noreferrer">${esc(state.cache.source)} ↗</a>`:`<p>${esc(state.cache.source)}</p>`}<div class="dialog-actions"><button data-action="close-dialog">取消</button><button class="primary" data-save="${id}">保存修改</button></div>`;dialog.showModal()}
function segmented(key,options){return `<div class="segmented" role="group" aria-label="${key}">${options.map(([v,label])=>`<button data-setting="${key}" data-value="${v}" class="${String(state[key])===String(v)?'active':''}" aria-pressed="${String(state[key])===String(v)}">${label}</button>`).join('')}</div>`}
function row(title,desc,control){return `<div class="setting-row"><div>${title}${desc?`<p>${desc}</p>`:''}</div>${control}</div>`}
function settingsPage(){let panel='';if(state.settingsTab===0)panel=`<h3>字幕外观</h3>${row('字幕主题','',segmented('theme',[['dark','深色'],['light','浅色']]))}${row('字号','',`<div class="range-control"><input aria-label="字幕字号" id="font-size" type="range" min="16" max="32" value="${state.size}"><span id="font-value">${state.size}px</span></div>`)}${row('背景不透明度','',`<div class="range-control"><input aria-label="背景不透明度" id="opacity" type="range" min="50" max="100" value="${state.opacity}"><span id="opacity-value">${state.opacity}%</span></div>`)}${row('窗口位置','',segmented('dock',[[true,'底部停靠'],[false,'自由悬浮']]))}`;
if(state.settingsTab===1)panel=languagePanel();
if(state.settingsTab===2)panel=`<h3>知识与存储</h3>${row('自动缓存知识','生成后保存到本地',`<button class="switch ${state.autoCache?'on':''}" role="switch" aria-label="自动缓存知识" aria-checked="${state.autoCache}" data-action="toggle-cache"></button>`)}${row('当前知识库',state.cache?esc(state.cache.name):'未选择',`<button class="small" data-go="${state.cache?'knowledge':'start'}">${state.cache?'查看知识':'开始创建'}</button>`)}${row('会话存档','结束后自动保存音频、原文和译文','<span class="service-mark">默认保存</span>')}`;
if(state.settingsTab===3)panel=`<h3>连接服务</h3><div class="connection"><div class="connection-head"><strong>OpenAI</strong><span class="service-mark">${state.connected?'已连接':'未连接'}</span></div><p>实时转录 + Luna 翻译</p><div class="key-placeholder">sk-••••••••••••••••••••••••</div><button class="small" data-action="connect">${state.connected?'重新连接':'连接'}</button></div><div class="connection"><div class="connection-head"><strong>Soniox</strong><span class="hint">可选服务</span></div><p>转录、说话人区分与翻译</p><button class="small" disabled style="margin-top:12px">待接入</button></div>`;
return `${pageTitle('MAKE IT FEEL LIKE YOU','偏好设置','')}<div class="settings-layout"><div class="settings-menu" aria-label="设置分类">${['字幕外观','语言与翻译','知识与存储','连接服务'].map((n,i)=>`<button data-settings-tab="${i}" class="${state.settingsTab===i?'active':''}" aria-pressed="${state.settingsTab===i}">${n}</button>`).join('')}</div><div><div class="settings-panel"><div class="settings-group">${panel}</div>${state.settingsTab<2?`<div class="settings-preview"><small>字幕预览</small><div id="settings-stage" class="${state.dock?'':'floating-preview'}">${captionBox()}</div></div>`:''}</div></div></div>`}

function captionBox(){return `<div class="caption-box"><div class="cap-meta"><button class="speaker-edit" data-action="speaker" aria-label="修改说话人姓名"><span class="cap-dot">●</span><span class="speaker-name">${esc(state.speaker)}</span> <span class="edit-hint">编辑</span></button><span class="cap-status"></span></div><div class="cap-copy"><div class="cap-zh"></div><div class="cap-en"></div></div></div>`}
function captionsPage(){return `${pageTitle('','当前会话','','<button class="small" data-go="settings">字幕设置</button>')}<div class="session-toolbar"><div class="session-source"><span class="source-icon">▣</span><div><strong>系统音频</strong><small>${languageName(languageUI.source)} <span>→</span> ${languageName(languageUI.target)}</small></div></div><div class="session-actions">${state.started?'<button class="small" data-action="focus-session">专注字幕 ↗</button>':''}${state.started?'<button class="small" data-action="stop">结束</button>':''}<button class="primary" data-action="play">${state.playing?'Ⅱ 暂停':state.started?'▷ 继续字幕':'▷ 开始字幕'}</button></div></div><div class="session-context"><span class="status-pill ${state.playing?'listening':''}"><i></i>${state.playing?'演示录音中 · 自动保存':state.started?'已暂停':'就绪'}</span><button class="context-link" data-go="knowledge">${state.cache?esc(state.cache.name):'选择知识库'} <span>⌄</span></button><div class="layout-options">${segmented('preview',[[false,'字幕记录'],[true,'外观预览']])}</div></div>${state.preview?`<div class="video-stage"><div class="lecture"><small>LLVM DEVELOPERS’ MEETING</small><h2>Understanding the<br>Clang front end.</h2><div class="lecture-rule"></div><p>From source code to meaning.</p></div>${captionBox()}</div>`:`<div class="transcript-panel"><div class="transcript-heading"><span>当前会话</span><span>${languagePair()}</span></div><div id="history" class="history"></div><div class="current-caption">${captionBox()}</div></div>`}<div class="session-bottom"><span class="duration" id="duration">00:00</span><span class="session-cost">本次预计费用 <strong>$0.00</strong></span></div><div class="window-launcher"><div><span class="window-symbol">▣</span><span><strong>独立字幕窗</strong><small>${state.overlay?'已打开 · '+(state.dock?'底部停靠':'自由悬浮'):'在其他窗口上方阅读字幕'}</small></span></div><div class="window-launcher-actions">${segmented('dock',[[true,'底部停靠'],[false,'自由悬浮']])}<button class="small" data-action="overlay">${state.overlay?'隐藏字幕窗':'打开字幕窗'}</button></div></div>`}
function text(el,value){if(el&&el.textContent!==value)el.textContent=value}
function clockText(t){return String(Math.floor(t/60)).padStart(2,'0')+':'+String(Math.floor(t%60)).padStart(2,'0')}
function updateCaption(){const sample=sessionText();let zh=sample.zh,en=sample.en;if(!state.started&&state.tick===0&&!state.preview&&state.page!=='settings'){zh='准备好后，开始字幕';en=''}
document.querySelectorAll('.caption-box').forEach(box=>{box.classList.toggle('light',state.theme==='light');box.classList.toggle('zh-only',languageUI.mode==='translation');box.classList.toggle('source-only',languageUI.mode==='original');box.classList.toggle('original-first',state.originalFirst);box.style.backgroundColor=state.theme==='light'?`rgba(255,255,255,${state.opacity/100})`:`rgba(31,34,32,${state.opacity/100})`;box.querySelector('.cap-zh').style.fontSize=state.size+'px';text(box.querySelector('.cap-zh'),zh);text(box.querySelector('.cap-en'),en);text(box.querySelector('.speaker-name'),state.speaker);text(box.querySelector('.cap-status'),state.playing?'实时更新':state.started?'已暂停':state.tick?'已结束':'准备就绪')});text($('#duration'),clockText(state.tick));
const h=$('#history');if(h&&h.dataset.length!==String(state.history.length)){const follow=h.scrollHeight-h.scrollTop-h.clientHeight<32;h.dataset.length=state.history.length;h.innerHTML=state.history.length?state.history.map(x=>`<div class="history-line"><span>${clockText(x.time)}</span><div><p>${esc(x.zh)}</p>${state.bilingual?`<small>${esc(x.en)}</small>`:''}</div></div>`).join(''):'<div class="history-empty"><span class="empty-signal">▥</span><p>字幕会随发言出现在这里</p></div>';if(follow)h.scrollTop=h.scrollHeight}}
function animate(now){if(!state.playing)return;state.tick+=(lastFrame?Math.min(200,now-lastFrame):0)/1000;lastFrame=now;state.history=demoRecord.lines.filter((x,i)=>i+1<demoRecord.lines.length&&demoRecord.lines[i+1].time<=state.tick).map(x=>({...x}));if(now-lastDraw>70){updateCaption();lastDraw=now}if(state.tick>=demoRecord.duration){state.tick=demoRecord.duration;stop();return}raf=requestAnimationFrame(animate)}
function play(){if(!state.started){state.started=true;state.tick=0;state.history=[]}state.playing=!state.playing;cancelAnimationFrame(raf);lastFrame=0;if(state.playing)raf=requestAnimationFrame(animate);render()}
function stop(){if(!state.started)return;state.focused=false;state.playing=false;state.started=false;state.overlay=false;cancelAnimationFrame(raf);autoArchiveSession()}
function syncOverlay(){let w=$('#subtitle-window');if(!w){w=document.createElement('section');w.id='subtitle-window';w.setAttribute('aria-label','独立字幕窗');w.innerHTML=`<header class="subtitle-title" data-drag><span class="subtitle-brand"><span>▥</span> livecap <small id="overlay-status"></small></span><span class="grip" aria-hidden="true">⠿</span><div class="subtitle-tools"><button data-action="overlay-play" aria-label="暂停或继续字幕">Ⅱ</button><button data-action="overlay-dock" aria-label="切换字幕停靠方式">▱</button><button data-go="settings" aria-label="打开字幕设置">⚙</button><button data-action="overlay" aria-label="关闭独立字幕窗">×</button></div></header>${captionBox()}`;document.body.append(w);new ResizeObserver(()=>{document.documentElement.style.setProperty('--subtitle-height',w.offsetHeight+'px');clampOverlay()}).observe(w)}w.hidden=!state.overlay;w.classList.toggle('docked',state.dock);w.classList.toggle('light',state.theme==='light');text($('#overlay-status'),state.playing?'演示中 · 自动保存':state.started?'已暂停':'就绪');text(w.querySelector('[data-action="overlay-play"]'),state.playing?'Ⅱ':'▷');w.querySelector('[data-action="overlay-dock"]').setAttribute('aria-label',state.dock?'改为自由悬浮':'停靠到底部');document.body.classList.toggle('caption-docked',state.overlay&&state.dock);if(state.overlay&&!state.dock)clampOverlay()}
function clampOverlay(){const w=$('#subtitle-window');if(!w||state.dock||!state.overlay)return;const r=w.getBoundingClientRect();w.style.left=Math.max(8,Math.min(r.left,innerWidth-r.width-8))+'px';w.style.top=Math.max(8,Math.min(r.top,innerHeight-r.height-8))+'px';w.style.bottom='auto'}
let drag;
document.addEventListener('pointerdown',e=>{const h=e.target.closest('[data-drag]');if(!h||e.target.closest('button')||e.button!==0)return;const w=$('#subtitle-window'),r=w.getBoundingClientRect();drag={x:e.clientX,y:e.clientY,left:r.left,top:r.top,id:e.pointerId,moved:false};h.setPointerCapture(e.pointerId)});
document.addEventListener('pointermove',e=>{if(!drag||e.pointerId!==drag.id)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!drag.moved&&Math.hypot(dx,dy)<4)return;const w=$('#subtitle-window');if(!drag.moved){drag.moved=true;if(state.dock){state.dock=false;syncOverlay();drag.left=Math.max(8,Math.min(drag.x-w.offsetWidth/2,innerWidth-w.offsetWidth-8));drag.top=Math.min(drag.top,innerHeight-w.offsetHeight-8)}}w.style.left=drag.left+dx+'px';w.style.top=drag.top+dy+'px';clampOverlay()});
function endDrag(){if(drag?.moved)render();drag=null}document.addEventListener('pointerup',endDrag);document.addEventListener('pointercancel',endDrag);
window.addEventListener('resize',clampOverlay);
document.addEventListener('dblclick',e=>{if(e.target.closest('[data-drag]')&&!e.target.closest('button')){state.dock=!state.dock;render()}});
document.addEventListener('click',e=>{const nav=e.target.closest('a[data-nav]');if(nav){state.focused=false;state.selectedRecord=null;if(location.hash===nav.getAttribute('href'))render();return}const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;if(workspaceClick(b))return;if(d.record!==undefined){state.selectedRecord=d.record==='demo'?'demo':Number(d.record);recordUI.tab='minutes';recordUI.selected=-1;recordUI.transcriptQuery='';go('records');render();return}if(d.space){state.knowledgeTab=d.space;state.selectedRecord=null;render();return}if(d.go){state.focused=false;state.selectedRecord=null;go(d.go);return}if(d.domain!==undefined){state.domain=Number(d.domain);state.focus=domains[state.domain].focus[0]||'';render();return}if(d.focus){state.focus=d.focus;render();return}if(d.term!==undefined){openTerm(Number(d.term));return}if(d.save!==undefined){const entry=state.cache.entries.find(x=>x.id===Number(d.save));const value=$('#translation-edit').value.trim();if(!value){$('#translation-edit').focus();return}entry.translation=value;persist();$('#detail').close();render();toast('已保存');return}if(d.settingsTab!==undefined){state.settingsTab=Number(d.settingsTab);render();return}if(d.setting){state[d.setting]=d.value==='true'?true:d.value==='false'?false:d.value;render();return}switch(d.action){case'onboard-next':state.onboardStep=Math.min(3,state.onboardStep+1);render();break;case'onboard-back':state.onboardStep=Math.max(0,state.onboardStep-1);render();break;case'finish-onboarding':finishOnboarding();break;case'demo-connect':state.connected=true;render();break;case'reconfigure':state.onboarding=true;state.onboardStep=0;render();break;case'launch-session':state.overlay=true;state.focused=true;play();break;case'focus-session':state.overlay=true;state.focused=true;render();break;case'unfocus':state.focused=false;render();break;case'back-records':state.selectedRecord=null;render();break;case'save-record':saveRecord();break;case'generate':beginGeneration();break;case'pause-generation':state.paused=!state.paused;b.textContent=state.paused?'继续':'暂停';updateProgress();break;case'cancel-generation':clearInterval(state.timer);state.generating=false;render();toast('已取消');break;case'close-dialog':$('#detail').close();break;case'export':{const blob=new Blob([JSON.stringify(state.cache,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=state.cache.slug+'.example.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出');break}case'toggle-cache':state.autoCache=!state.autoCache;render();break;case'connect':b.disabled=true;b.textContent='验证连接中…';setTimeout(()=>{state.connected=true;if(state.page==='settings')render();toast('连接成功')},1000);break;case'play':case'overlay-play':play();break;case'stop':stop();break;case'overlay':state.overlay=!state.overlay;if(!state.overlay)state.focused=false;render();break;case'overlay-dock':state.dock=!state.dock;render();break;case'speaker':{const dialog=$('#detail');dialog.innerHTML=`<div class="dialog-top"><h2>说话人姓名</h2></div><input id="speaker-input" aria-label="说话人姓名" maxlength="40" value="${esc(state.speaker)}"><div class="dialog-actions"><button data-action="close-dialog">取消</button><button class="primary" data-action="save-speaker">保存</button></div>`;dialog.showModal();break}case'save-speaker':state.speaker=$('#speaker-input').value.trim()||'说话人 1';$('#detail').close();updateCaption();break;case'restart':state.tick=0;updateCaption();toast('字幕已回到开头');break}});
document.addEventListener('input',e=>{if(e.target.id==='custom'){state.custom=e.target.value;const b=$('[data-action="generate"]');b.disabled=!state.custom.trim()}if(e.target.id==='search')$('#terms').innerHTML=termCards(e.target.value);if(e.target.id==='font-size'){state.size=Number(e.target.value);$('#font-value').textContent=state.size+'px';updateCaption()}if(e.target.id==='opacity'){state.opacity=Number(e.target.value);$('#opacity-value').textContent=state.opacity+'%';updateCaption()}});
window.addEventListener('hashchange',render);render();
